// Base64 del logotipo oficial de la Corporación Universitaria Latinoamericana (CUL)
export const UNIVERSITY_LOGO_BASE64 = "";

export function getUniversityLogoUint8Array(): Uint8Array {
  const binaryString = atob(UNIVERSITY_LOGO_BASE64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}
